/*
 * Dev-only service worker stub.
 *
 * The real workbox SW is generated by next-pwa during `next build` and
 * overwrites this file. In development next-pwa is disabled, so we ship a
 * self-unregistering stub here: any browser that previously registered
 * the production SW will fetch this file, unregister it, and clear its
 * caches — fixing stale-chunk errors ("module factory is not available")
 * caused by the old SW serving outdated `/_next/static/*` chunks.
 */
self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((k) => caches.delete(k)));
      await self.registration.unregister();
      const clients = await self.clients.matchAll({ type: "window" });
      for (const c of clients) {
        c.navigate(c.url);
      }
    })(),
  );
});
